------------------------------------------------------------------------------------------------
-- 4. Verificación
------------------------------------------------------------------------------------------------
SET @sql = N'SELECT ''DESPUES'' AS Momento, [Cód_ Acumulador] AS Acumulador, COUNT(*) AS Filas
             FROM [dbo].' + @Tabla + N' GROUP BY [Cód_ Acumulador] ORDER BY 3 DESC;';
EXEC sp_executesql @sql;

-- Total esperado: 1208. REMUNERATIVO_BRUTO 152, BASE_LRT 137, BASE_SINDICAL 130,
-- BASE_OS_TRAB 128, BASE_IG4 123, BASE_PROMEDIO 124, BASE_SAC 119, BASE_SS_TRAB 117.
SET @sql = N'SELECT COUNT(*) AS TotalFilas FROM [dbo].' + @Tabla + N';';
EXEC sp_executesql @sql;

-- Huérfanos: no debería devolver nada.
SET @sql = N'SELECT DISTINCT f.[Cód_ Concepto], f.[Cód_ Acumulador]
             FROM [dbo].' + @Tabla + N' f
             LEFT JOIN (SELECT DISTINCT [Código] FROM [dbo].' + QUOTENAME(@Empresa + N'$Concepto Liquidación$' + @Ext) + N') c
                    ON c.[Código] = f.[Cód_ Concepto]
             LEFT JOIN (SELECT DISTINCT [Código] FROM [dbo].' + QUOTENAME(@Empresa + N'$Concepto Liquidación$' + @Ext) + N') a
                    ON a.[Código] = f.[Cód_ Acumulador]
             WHERE c.[Código] IS NULL OR a.[Código] IS NULL;';
EXEC sp_executesql @sql;

-- Candidatos a revisar "Invertir Signo" a mano: conceptos que restan.
SET @sql = N'SELECT DISTINCT f.[Cód_ Concepto], c.[Descripción], c.[Tipo Concepto]
             FROM [dbo].' + @Tabla + N' f
             JOIN [dbo].' + QUOTENAME(@Empresa + N'$Concepto Liquidación$' + @Ext) + N' c
               ON c.[Código] = f.[Cód_ Concepto]
             WHERE c.[Tipo Concepto] IN (2,4,5)
             ORDER BY 1;';
EXEC sp_executesql @sql;
GO
